    QOL_NAV_BARSCALE = "Bar scale",
    QOL_NAV_WHOCOOLDOWN = "/who cooldown",
    QOL_ABOUT_WHOCOOLDOWN = "After a /who, the server refuses another for a moment. The time left shows on the Who list's search button (Refresh, ClassicUI's too): a line crossing it from left to right, or the seconds left in place of its text, and a light flash when /who is ready again. 7 seconds between two /who; a /who sent meanwhile does not start it again (the server refuses it). Neither box ticked: nothing shown.",
    WHO_CD_BAR      = "Progress bar: a line crosses the button, a flash when /who is ready",
    WHO_CD_COUNT    = "Countdown: the seconds left in place of the button's text, a flash at the end",
    QOL_ABOUT_BARSCALE = "One slider for the action bars, the micro menu and the bags, all at once (50 to 200 %), with the game's own bars or ClassicUI's classic bar: they keep their place and stay together. Out of combat (in a fight, once it ends). Command: /barscale 120.",
    BS_TITLE        = "Bar scale",
    BS_SLIDER       = "Action bars, micro menu and bags",
