    BS_COMMAND      = "Bar scale: %d %%. /barscale 120 sets it (50 to 200).",
    QOL_NAV_TOOLTIPANCHOR = "Tooltip Anchor",
    QOL_ABOUT_TOOLTIPANCHOR = "Where the tooltips the game puts in its corner open (the characters and creatures of the world, and the frames that leave it to the game): in the game's place, at the mouse (following it), or at an anchor you move (Tooltip Anchor, its cross puts it away). Held by the corner you pick: bottom right by default, or top right, bottom left, top left. Its page: Esc > Options > AddOns > Clara > Interface > Tooltip Anchor.",
    QOL_NAV_IDTIP   = "idTip",
    QOL_ABOUT_IDTIP = "Adds the IDs of what a tooltip shows, each on a line of its own: SpellID, ItemID, NpcID, QuestID, CurrencyID, EnchantID, IconID, and more. Each kind can be turned off on its page (Esc > Options > AddOns > Clara > Interface > idTip). Command: /idtip.",
