    EC_INSTANTS     = "Instant spells",
    EC_INSTANTS_TIP = "The instant spells an enemy uses, each shown for a moment.",
    EC_NAMES        = "The spell's name under its icon",
    EC_ENEMIES      = "Enemies only",
