    QOL_NAV_LFGFOREVER = "LFG Forever",
    QOL_ABOUT_LFGFOREVER = "La recherche de groupe du jeu dans une seule fenêtre : groupes et joueurs dans une seule liste, filtrés par rôle, classe, niveau, style de jeu et langue, avec Demander à rejoindre et Inviter qui chuchotent ton message, un journal des chuchotements reçus et des filtres enregistrés. Le panneau des filtres, à droite, se ferme avec la flèche en haut à droite de la liste (fermé tant que tu ne l'ouvres pas), avec un bouton Relancer la recherche à côté. Commande : /lfg, ou son raccourci, son bouton de minicarte, ou son onglet dans la recherche de groupe du jeu.",
    LFGFOREVER_BINDING = "Ouvrir LFG Forever",
    QOL_NAV_WHATSTRAINING = "What's Training?",
