    NS_SW_ORE       = "Funkeln auf Erzen",
    MENU_CAMERA     = "Dynamische Kamera",
    DC_SW_ON        = "DynamicCam an, mit vertikaler Neigung und Kopfverfolgung, Pitch (on ground) auf 0,99 (aus: DynamicCam sofort ganz aus, die Kamera des Spiels zoomt mit 15 bis 50 Meter)",
    QOL_ABOUT_DYNAMICCAM = "Eine dynamischere Kamera: Zoom, Schulterversatz, Neigung und Drehung, die sich mit deinem Tun ändern (Kampf, beritten, in der Stadt, im Dungeon...), weicheres Zoomen und ein ausgeblendetes Interface, wann du willst. Ein Kästchen im Menü des Porträts schaltet sie mit einem Klick ein oder aus, ohne Neuladen: angehakt läuft DynamicCam mit vertikaler Neigung und Kopfverfolgung, Pitch (on ground) auf 0,99; aus ist sie ganz abgeschaltet und die Kamera des Spiels zoomt mit 15 bis 50 Meter. Standard: Camera Zoom Speed 15, Maximum Camera Distance 50, Use Reactive Zoom aus. Befehl: /dc.",
    QOL_ABOUT_DIALOGKEY = "Eine Taste (standardmäßig Leertaste) klickt den ersten Knopf eines Dialogs, nimmt Quests an und schließt sie ab; Zifferntasten wählen Gesprächsoptionen und Questbelohnungen. Nicht im Kampf. Befehl: /dialogkey (/dk).",
    QOL_ABOUT_XTOLEVEL = "Wie viele Gegner, Quests, Dungeons und Schlachtfelder bis zur nächsten Stufe bleiben, nach deinen eigenen Durchschnitten: in einem kleinen Fenster (ziehen; Rechtsklick: seine Optionen), einem LibDataBroker-Feed und den Tooltips. Befehl: /xtl.",
    QOL_ABOUT_MINIMAPDRAWER = "Sammelt die Minimap-Knöpfe der Addons in einer Schublade, die sich an deinem Stufenkreis öffnet (kurz darüberfahren oder anklicken). Ein Symbol aus der Schublade ziehen, um es frei zu platzieren; auf die offene Schublade fallen lassen, um es zurückzulegen; eines über ein anderes ziehen, um die Reihenfolge zu ändern. Das Schloss der Schublade verschiebt Schublade und Kreis. Befehl: /mmd.",
    MMD_SW_HOVER    = "Schublade beim Überfahren des Stufenkreises öffnen (ein Klick öffnet sie immer)",
    MMD_SW_PORTRAIT = "Ein doppelter Mittelklick auf dein Porträt lädt das Interface neu",
    QOL_NAV_MAIL    = "Post",
    QOL_ABOUT_MAIL  = "Ein Knopf rechts von „An“ im Fenster Post versenden: die Charaktere, denen du Post geschickt hast, die neuesten zuerst, drei pro Zeile (das Mausrad zeigt ältere); ein Klick setzt einen in „An“. Rechtsklick auf einen Namen ordnet den Charakter Kategorien zu (Main/Twink, Bank-Twink, Freund, Kunde und deine eigenen); Sortieren holt die Charaktere einer Kategorie nach oben, eingerahmt. Deine eigenen Charaktere kommen ab Stufe 3 als Main/Twink in die Liste. Export / Import gibt alles an einen anderen Account weiter.",
    QOL_NAV_MONEY = "Gold der Charaktere",
    QOL_ABOUT_MONEY = "Rechtsklick auf das Geld unten im Rucksack: das Gold aller deiner Charaktere, eine Spalte pro WoW-Account (nach seinem Ordner benannt: ICKSTU, WANJ, WoW1…; Rechtsklick auf einen Namen zum Umbenennen), die höchste Stufe oben, die Summe jedes Accounts und aller zusammen. Umsortieren: zieh einen Charakter, die anderen weichen beim Ziehen aus. Entferne das Häkchen eines Accounts, um seine Spalte zu einem schmalen Streifen einzuklappen; ein Klick auf den Streifen zeigt sie wieder. Die Charaktere der anderen Accounts kommen über die Synchronisierung (live, wenn beide online sind, sonst über das Windows-Skript).",
    QOL_NAV_LOFPLUS = "LootOptimizer Forever",
    QOL_ABOUT_LOFPLUS = "Neben LootOptimizer Forever (ein eigenes Addon, nötig: installiere es): sein Fenster bei vollen Taschen kompakt (ohne Porträt, ohne das leere Band unter dem Titel, kleiner), kein Fenster, wenn die Beute weniger wert ist als jeder Gegenstand in den Taschen, den sie ersetzen könnte (stattdessen eine Chatzeile, die Beute bleibt auf der Leiche), und seine Fenster in Claras Aussehen (dem von ClassicUI, wenn es läuft). Sein Knopf öffnet das Fenster von LOF.",
    LOFPLUS_COMPACT = "Kompaktes Fenster bei vollen Taschen",
    LOFPLUS_QUIET = "Kein Fenster, wenn die Beute weniger wert ist als jeder Gegenstand in den Taschen",
    LOFPLUS_NOT_WORTH = "lohnt sich nicht: %s (%s) bleibt auf der Leiche; dein billigster Gegenstand in den Taschen ist %s wert.",
    QOL_NAV_PRICES = "Auktionshauspreise geteilt",
    QOL_ABOUT_PRICES = "Die Auktionshauspreise, auf allen deinen WoW-Accounts gleich: jeder Preis, den ein Scan sieht (die Scans von Auctionator: es muss installiert sein), wird behalten, der neueste jedes Gegenstands. Live, solange zwei deiner Accounts online sind (die Synchronisierung): die neuen Preise der Gegenstände, die deine Charaktere besitzen, höchstens alle 20 Sekunden, nie ein ganzer Scan (das würde den Server fluten). Zwischen zwei Sitzungen: alle, durch das Windows-Skript (Ordner Synchro: Installer.bat erneut ausführen). Ein neuerer Preis eines anderen Accounts geht in die Preise von Auctionator selbst, die seine Tooltips und LootOptimizer Forever lesen. Unabhängig von jedem Scanner: Auctionator allein genügt, um es zu füllen.",
    QOL_NAV_SNIPER = "Sniper",
    QOL_ABOUT_SNIPER = "Ein Sniper für das Auktionshaus, in einem eigenen Reiter neben denen von Auctionator (nötig: installiere es). Gestartet durchsucht er das ganze Auktionshaus immer wieder und listet sofort die Gegenstände, deren niedrigster Preis um einen bestimmten Anteil unter ihrem üblichen Preis liegt, die besten zuerst. Ihr üblicher Preis: der Median oder der Durchschnitt der niedrigsten Tagespreise über 24 Stunden, 3, 7, 15 oder 30 Tage, 3, 6 oder 12 Monate oder alle Zeit, mit einem Klick; der Anteil mit dem Schieberegler des Reiters oder in sein Feld getippt. Ein Klick auf eine Zeile öffnet den Gegenstand in der Kaufansicht des Spiels (ein Klick pro Kauf).",
    SNIPER_TAB = "Sniper",
    SNIPER_HEADER = "Sniper: Gegenstände weit unter ihrem üblichen Preis",
