    QOL_NAV_BARSCALE = "Leistengröße",
    QOL_NAV_WHOCOOLDOWN = "/who-Wartezeit",
    QOL_ABOUT_WHOCOOLDOWN = "Nach einem /who lehnt der Server einen weiteren eine Weile ab. Die verbleibende Zeit erscheint auf der Suchschaltfläche der Wer-Liste (Refresh, auch der von ClassicUI): ein Strich, der sie von links nach rechts durchquert, oder die verbleibenden Sekunden anstelle ihres Textes, und ein leichtes Aufleuchten, sobald /who wieder geht. 7 Sekunden zwischen zwei /who; ein /who in der Zwischenzeit startet sie nicht neu (der Server lehnt ihn ab). Keines der beiden Kästchen angehakt: nichts wird angezeigt.",
    WHO_CD_BAR      = "Fortschrittsbalken: ein Strich durchquert die Schaltfläche, ein Aufleuchten, sobald /who geht",
    WHO_CD_COUNT    = "Countdown: die verbleibenden Sekunden anstelle des Textes, ein Aufleuchten am Ende",
    QOL_ABOUT_BARSCALE = "Ein Schieberegler für die Aktionsleisten, das Mikromenü und die Taschen, alle zusammen (50 bis 200 %), mit den Leisten des Spiels oder der klassischen Leiste von ClassicUI: Sie behalten ihren Platz und bleiben zusammen. Außerhalb des Kampfes (im Kampf, sobald er endet). Befehl: /barscale 120.",
    BS_TITLE        = "Leistengröße",
    BS_SLIDER       = "Aktionsleisten, Mikromenü und Taschen",
    BS_SLIDER_TIP   = "Ihre Größe, alle zusammen, zusätzlich zu der, die der Bearbeitungsmodus jeder gibt (oder der Leiste von ClassicUI).",
    BS_DEFAULT      = "Standard (100 %)",
    BS_DEFAULT_TIP  = "Zurück zu ihrer eigenen Größe.",
    BS_COMMAND      = "Leistengröße: %d %%. /barscale 120 stellt sie ein (50 bis 200).",
    QOL_NAV_TOOLTIPANCHOR = "Tooltip Anchor",
    QOL_ABOUT_TOOLTIPANCHOR = "Wo sich die Tooltips öffnen, die das Spiel in seine Ecke setzt (die Charaktere und Kreaturen der Welt und die Fenster, die das dem Spiel überlassen): am Platz des Spiels, an der Maus (sie folgen ihr) oder an einem Anker, den du verschiebst (Tooltip Anchor, sein Kreuz räumt ihn weg). Gehalten an der gewählten Ecke: unten rechts standardmäßig, oder oben rechts, unten links, oben links. Seine Seite: Esc > Optionen > AddOns > Clara > Oberfläche > Tooltip Anchor.",
    QOL_NAV_IDTIP   = "idTip",
    QOL_ABOUT_IDTIP = "Fügt die IDs dessen hinzu, was ein Tooltip zeigt, jede in einer eigenen Zeile: SpellID, ItemID, NpcID, QuestID, CurrencyID, EnchantID, IconID und weitere. Jede Art lässt sich auf ihrer Seite abschalten (Esc > Optionen > AddOns > Clara > Oberfläche > idTip). Befehl: /idtip.",
    IDT_SW_ON       = "IDs in den Tooltips anzeigen",
