    IDT_SEC_COLLECTIONS = "Sammlungen",
    QOL_NAV_SOLORAIDFRAME = "Solo Raid Frame",
    QOL_ABOUT_SOLORAIDFRAME = "Lässt den Gruppenrahmen im Schlachtzugsstil des Spiels sichtbar, solange du in keiner Gruppe bist: dein eigener Rahmen ist auch beim Solospiel da (Bearbeitungsmodus: Gruppenrahmen, Schlachtzugsstil verwenden). In einer Gruppe gilt die Regel des Spiels. Endet eine Gruppe (jemand geht, eine Einladung abgelehnt), kommt er sofort zurück, auch im Kampf (über den sicheren Zustandstreiber des Spiels). Keine Einstellungen.",
    QOL_NAV_ENHANCEDRAIDFRAMES = "Enhanced Raid Frames",
    QOL_ABOUT_ENHANCEDRAIDFRAMES = "Auf den Schlachtzugsrahmen des Spiels (und Gruppenrahmen im Schlachtzugsstil): bis zu neun Anzeigen pro Rahmen, jede zeigt die Auren deiner Liste (nach Name, Zauber-ID oder Debuff-Typ: Magic, Curse, Poison, Disease, Dispel), als Symbol oder farbiges Quadrat, mit Restzeit, Stapeln und Farben; Schlachtzugsmarkierungen; Skalierung der Rahmen, Deckkraft des Hintergrunds und außer Reichweite. Für WoW Forever umgebaut: im Kampf zeigt das Spiel selbst die Buffs und Debuff-Typen deiner Liste. Befehl: /erf.",
    ERF_SW_MARKERS  = "Schlachtzugsmarkierungen auf den Rahmen",
    QOL_NAV_DOESITDIE = "DoesItDie",
    QOL_ABOUT_DOESITDIE = "Deine DoTs auf dem Ziel: der Schaden, den sie noch anrichten, wird auf seiner Gesundheitsleiste markiert (auch beim Fokus und den Namensplaketten), mit einem Todessymbol auf dem Porträt, wenn sie es erledigen. Für WoW Forever gemacht: der Vergleich mit der geheimen Gesundheit erfolgt durch die Leisten des Spiels selbst. Standardmäßig im Aussehen des Spiels (Textur der Gesundheitsleiste, ein dunkles Rot, der Boss-Totenkopf des Spiels); das Optionsfenster hat eine Live-Vorschau und die anderen Looks von DoesItDie. Befehl: /did.",
    QOL_NAV_LFGFOREVER = "LFG Forever",
    QOL_ABOUT_LFGFOREVER = "Die Gruppensuche des Spiels in einem Fenster: Gruppen und Spieler in einer Liste, gefiltert nach Rolle, Klasse, Stufe, Spielstil und Sprache, mit Beitritt anfragen und Einladen, die deine Nachricht flüstern, einem Protokoll der empfangenen Flüsternachrichten und gespeicherten Filtern. Das Filterfeld rechts schließt sich mit dem Pfeil oben rechts an der Liste (geschlossen, bis du es öffnest), mit einem Knopf Erneut suchen daneben. Befehl: /lfg, oder seine Taste, sein Minikartenknopf oder sein Reiter in der Gruppensuche des Spiels.",
    LFGFOREVER_BINDING = "LFG Forever öffnen",
    QOL_NAV_WHATSTRAINING = "What's Training?",
    QOL_ABOUT_WHATSTRAINING = "Was dein Klassenlehrer (und die Waffenmeister, der Tierausbilder, die Folianten) dir beibringen kann, jetzt und auf den nächsten Stufen, mit den Kosten, und welche Rezepte deine Berufe noch lernen können und wo. In Forevers Zauberbuch: ein eigener Reiter auf den Seiten des Buchs; mit ClassicUIs Zauberbuch öffnet sein seitlicher Reiter die klassische Liste neben dem Buch. Befehl: /wt (sein Fenster).",
    QOL_NAV_ENEMYCASTS = "Feindliche Zauber",
    QOL_ABOUT_ENEMYCASTS = "Neben der Namensplakette eines Feindes, was er gerade getan hat: der Zauber, den er wirkt (sein Symbol, sein Name darunter), gehalten solange das Wirken dauert und rot getönt, wenn es unterbrochen wird, und die Spontanzauber, die er benutzt. Die letzten bleiben in einer Reihe, der neueste an der Plakette, jeder blendet nach einem Moment aus. Links oder rechts der Plakette oder darüber; Symbolgröße, wie viele bleiben und wie lange stehen auf seiner Seite (Esc > Optionen > AddOns > Clara > Kampf > Feindliche Zauber). Für WoW Forever gemacht: ein geheimer Zauber wird nie gelesen, das Spiel zeichnet ihn selbst. Claras eigener Code (nicht der von ForeverGCD).",
    EC_CASTS        = "Zauber, die gewirkt werden",
    EC_CASTS_TIP    = "Der Zauber, den ein Feind wirkt oder kanalisiert, gehalten solange er dauert (rot, wenn er unterbrochen wird).",
    EC_INSTANTS     = "Spontanzauber",
