    ALTS_RELOAD_PROFILE = "das angewendete Profil „%s“",
    RESET_ADDON_ASK = "Clara Combo Points zurücksetzen?\n\nAlle deine Einstellungen werden gelöscht: Die Reiter aller Klassen (Leisten, Farben, Schrift, Symbole) und das Optionsfenster kehren zum Standard zurück. Gespeicherte Profile bleiben erhalten.",
    RESET_ADDON     = "Zurücksetzen",
    -- Seite in den Spieloptionen (Esc > Optionen > AddOns)
    SP_RESET_POS    = "Optionsfenster zurückholen",
    SP_OPEN         = "Optionen öffnen (/cl)",
    SP_LOCK_ALL     = "Alles sperren",
    SP_UNLOCK       = "Leiste entsperren",
    SP_RESET_ADDON  = "Addon zurücksetzen...",
    SP_WINDOW_SIZE  = "Größe des Optionsfensters",
    SP_DEFAULT_SIZE = "Standardgröße",
    SP_HINT         = "Das Optionsfenster lässt sich am Titel verschieben, auch aus dem Bildschirm, und an der unteren rechten Ecke vergrößern oder verkleinern. /cl reset pos holt es ebenfalls zurück.",
    SP_HOW          = "So funktioniert's",
    SP_README       = "|cffffd200Was das Addon macht|r\nEine Leiste für alle Klassen: Combopunkte (Schurken, Druiden), Energie oder Wut (Schurken, Druiden, Krieger), Mana, Gesundheit und bis zu drei Symbolzeilen darüber und darunter, um Buffs, Debuffs und Abklingzeiten zu verfolgen. Druiden sehen Combopunkte und Energie / Wut in Katzen- und Bärengestalt (einstellbar).\n\n|cffffd200Die Optionen|r\n/cl (oder /clara, /ccp, /cp) öffnet das Fenster auf dem zuletzt gezeigten Reiter und der zuletzt gezeigten Seite (beim ersten Mal auf dem Reiter deiner Klasse). Jeder Klassenreiter hat eigene Einstellungen, auf fünf Seiten in der Liste links: Allgemein (Größe, Deckkraft, Stil und Text der Leisten), Leisten (Reihenfolge, Größe und Farben jeder Leiste), Symbole, Sichtbarkeit (Addon anzeigen oder ausblenden, Druidengestalten, Menü des Porträts) und Profile. Eine Seite in der Liste ziehen, um ihren Platz zu ändern; Rechtsklick auf das Porträt gibt dem Reiter das Symbol einer Spezialisierung. Das Fenster lässt sich am Titel verschieben, auch aus dem Bildschirm. Seine untere rechte Ecke ändert seine Größe: mit gedrückter linker Maustaste ziehen für Breite und Höhe (die Seiten scrollen, wenn es kleiner ist als sie), mit der rechten zum Vergrößern oder Verkleinern, Doppelklick für die Standardgröße. Seine Deckkraft wird unten rechts eingestellt.\n\n|cffffd200Deckkraft und Ausblenden|r\nRechtsklick auf dein Porträt: am Ende des Menüs (das Spiel lässt Addons nur nach seinen eigenen Einträgen etwas hinzufügen; nicht im Kampf) hat der Abschnitt Clara Combo Points Interface neu laden, einen Regler für die Deckkraft der Leiste, gefolgt von zwei Kästchen: Leiste und Symbole gesperrt für alle Klassen, dann das ganze Addon anzeigen / ausblenden (auch /cl hide und /cl show); darunter Schadensanzeige und Dynamische Kamera (vertikale Neigung und Kopfverfolgung von DynamicCam an oder aus, deine Zoom Schrittgröße für jeden Zustand), dann Angelmodus (Musik, Umgebung und Stimmen aus, Soundeffekte auf 100 %, um den Schwimmer zu hören; auch auf der Angel-Karte des Berufefensters, und oben mit der Lautstärke). Dieser Abschnitt und Interface neu laden lassen sich oben aus dem Menü nehmen.\n\n|cffffd200Die Leiste verschieben|r\nPosition (über den Klassenreitern) > Entsperren, dann die Leiste mit der linken Maustaste ziehen. Ihre Symbolzeilen öffnen sich auch, für alle Klassen: Zauber aus dem Zauberbuch oder Gegenstände aus den Taschen darauf ablegen, Symbole ziehen, Rechtsklick auf ein Symbol entfernt es. Danach wieder sperren (der Knopf, /cl lock oder Alles sperren oben).\n\n|cffffd200Symbole|r\nSeite Symbole: Namen oder ID eines Zaubers eingeben, einen Zauber aus dem Zauberbuch auf eine Zeile ziehen oder Klassenzauber öffnen, um einen Buff oder Debuff einer beliebigen Klasse, einen Zauber des Reiters Allgemein oder eines Volks mit Rang und Beobachtungsort zu wählen (Nur bekannte Zauber zeigen behält die deines Zauberbuchs; sein Schloss löst dieses Fenster, um es allein zu verschieben und zu skalieren, erneut gesperrt kommt es an die Seite des Fensters, an der es ist). Ein Zauber am Mauszeiger (aus dem Zauberbuch, dem Chat oder einer Aktionsleiste) oder aus dieser Liste gezogen öffnet die Zeilen der Leiste selbst, auch gesperrt: auf einer ablegen. Klick auf ein Symbol: auf dir, deinem Ziel, einem feindlichen oder einem freundlichen Ziel beobachten, Rang wählen oder entfernen. Rechtsklick oder aus dem Fenster ziehen: entfernen. Bei gesperrten Symbolen wirkt ein Klick auf ein Symbol der Leiste seinen Zauber, wenn dein Charakter ihn kennt; ein Zauber, der eine Gestalt oder Haltung braucht (Zermalmen, Sturmangriff...), nimmt zuerst diese Gestalt an, ein zweiter Klick wirkt ihn; Wilde Attacke: Linksklick Bärengestalt, Rechtsklick Katzengestalt. Ein gerade gelernter Zauber lässt sich aus seiner Chatzeile nehmen (auf seinen Namen drücken). Ein graues Symbol wartet auf seine Aura; der Bogen und die Restzeit zeigen ihre Dauer; ein Zauber mit Abklingzeit zeigt seine Abklingzeit.\n\n|cffffd200Gegenstände und Waffenverzauberungen|r\nEin Symbol kann ein Gegenstand sein: aus den Taschen ziehen (Leiste entsperrt). Es zeigt, wie viele du trägst, seine Abklingzeit und seinen Buff; ein Klick benutzt ihn. Gifte, Öle und Steine zeigen die Verzauberung deiner Waffe (Linksklick: Waffenhand, Rechtsklick: Schildhand). Die Waffenverzauberungen des Schamanen zeigen die Restzeit auf der Waffe; Waffe des Windzorns zeigt nach einem Extraangriff ihre interne Abklingzeit von 1,5 Sekunden. Während ein Zauber mit Zauberzeit gewirkt wird, sind seine Manakosten auf der Manaleiste markiert.\n\n|cffffd200Im Kampf|r\nDas Spiel verbirgt Auren im Kampf vor Addons. Es zeigt sie selbst in seinen Auren-Containern: Buffs auf dir oder einem freundlichen Ziel und Debuffs auf einem feindlichen Ziel werden weiter verfolgt. Ein Debuff auf dir oder ein Buff auf einem Feind wird nur außerhalb des Kampfes verfolgt. Bleibt ein Symbol im Kampf grau, /cl debug eingeben und die Ausgabe schicken.\n\n|cffffd200Profile|r\nSeite Profile: einen Namen eingeben, dann Speichern, um alle Einstellungen des Reiters zu behalten. Ein Profil in der Liste wählen, um es zu Laden oder zu Löschen. Exportieren gibt einen Text zum Kopieren; auf einem anderen Account Importieren und einfügen. Bevor ein anderes Profil geladen wird, bietet das Addon an, ungespeicherte Änderungen zu speichern. Beim Speichern In meiner Spezialisierung laden ankreuzen: das Profil lädt dann von selbst, sobald dein Charakter in dieser Spezialisierung ist.\n\n|cffffd200Eingebaute Module|r\nFunktionen anderer Addons sind eingebaut (nur in WoW Forever), unter dieser Seite nach Thema: Kampf, Oberfläche, Quests und Fortschritt, Wirtschaft und Berufe; jedes Modul mit seinem Kästchen, was es tut, und seinen eigenen Seiten unter seinem Thema. Die Optionen der Leiste stehen auf der ersten Seite (Clara Combo Points) oder in ihrem Fenster (/clara). Ist das Original-Addon eines Moduls aktiviert, läuft dieses für die Sitzung, dann wird es für den Charakter deaktiviert und die eingebaute Version übernimmt ab dem nächsten Neuladen (mit seinen Einstellungen).\n\n|cffffd200/who|r\n/who lea listet jeden Namen mit lea darin, wie das Spiel (Leah, Leafrunner...). /who \"lea\" (ein Wort in Anführungszeichen) listet nur Spieler, deren Vor- oder Nachname Lea ist, Akzente egal (Léa, Lëa; nicht Leah). Ein Kästchen weiter oben schaltet es aus.\n\n|cffffd200UnitScan|r\nEin Alarm, sobald ein seltener Gegner von WoW Forever, ein hinzugefügter Name oder der gejagte Gegner in Sicht ist (dein Ziel, der Mauszeiger, die Namensplaketten, die Ziele deiner Gruppe): ein Fenster zum Anklicken, um ihn ins Ziel zu nehmen, ein Ton, der Bildschirm blinkt, das Spielsymbol blinkt in der Taskleiste, während du in einem anderen Fenster bist. Die Sichtungen von UnitScan Hardcore Forever werden immer empfangen; deine werden nur gesendet, wenn du das Kästchen ankreuzt (aus). Esc > Optionen > AddOns > Clara > Quests und Fortschritt > UnitScan, oder /cl scan. Screenshots: bei jedem Stufenaufstieg und beim ersten Sieg über jeden Boss (Schlachtzüge, Dungeons ab 54, letzter Boss eines Levelling-Dungeons), pro Charakter.\n\n|cffffd200Befehle|r\n/cl lock  ·  /cl unlock  ·  /cl hide  ·  /cl show  ·  /cl scale 120 (Größe der Leiste, in %)  ·  /cl reset (alles auf Standard, nach Bestätigung)  ·  /cl reset pos (Optionsfenster in die Bildschirmmitte)  ·  /cl debug (Zustand der Symbole)  ·  /cl help  ·  /cl scan (UnitScan; /cl scan Name: einen Namen hinzufügen oder entfernen)  ·  /cl hunt Name (der gejagte Gegner)  ·  /rl (Interface neu laden)  ·  /ltp (Leatrix Plus)  ·  /wst (WeaponSwingTimer)  ·  /dc (DynamicCam)  ·  /dk (DialogKey)  ·  /xtl (XToLevel)  ·  /mmd (MinimapDrawer)  ·  /fcui (ClassicUI Forever)  ·  /buyemall confirm",
  },
}

ns.LANGUAGES = {
  { code = "frFR", name = "Français" },
  { code = "deDE", name = "Deutsch" },
  { code = "enUS", name = "English" },
}

local english = strings.enUS
local client = GetLocale and GetLocale()
ns.lang = strings[client] and client or "enUS"

function ns:IsLanguage(code)
  return strings[code] ~= nil
end

-- L.KEY always reads the current language, so switching language only needs a relabel.
ns.L = setmetatable({}, {
  __index = function(_, key)
    local text = strings[ns.lang][key]
    if text == nil then text = english[key] end
    return text
  end,
})
